      const h = harness([text('Half <thi')], {failWith: DROPPED});

      await h.send();

      const [, stored] = h.session.entries;
      expect({stored, resent: upsertsOf(h.sent, 1).at(-1)}).toMatchObject({
        stored: {content: 'Half <thi', truncated: true},
